# still not accurate 


# because python blocks more than 4300 digits , more importantly if the number is bigger the calculation causes more ram and storage. 
# and calculating 1000000! is useless where we just want to know how many digits in it. 



# calculating digits in big numbers 

import math

def factorial_digits(n):
    if n<=1 :
        return 1
    return int(
        n * math.log10(n / math.e) +
        0.5 * math.log10(2 * math.pi * n)
    ) + 1

res = factorial_digits(number)

print(f"There are {res} digits in {number}!")

